          "code": "import numpy as np\nfrom scipy import sparse\nfrom sklearn.decomposition import PCA, TruncatedSVD\n\nrng = np.random.default_rng(42)\n\n# 1. Matriks sparse interaksi pengguna-item (800 x 300, ~85% nol) -> TruncatedSVD\nn_users, n_items, k_latent = 800, 300, 6\nP = rng.normal(0.0, 1.0, size=(n_users, k_latent))\nQ = rng.normal(0.0, 1.0, size=(n_items, k_latent))\nsignal = P @ np.diag([12.0, 8.0, 5.5, 3.5, 2.0, 1.2]) @ Q.T\nmask = rng.random(size=(n_users, n_items)) < 0.15\nR_sparse = sparse.csr_matrix(np.where(mask, signal + rng.normal(0.0, 0.1, size=signal.shape), 0.0))\n\ntsvd = TruncatedSVD(n_components=k_latent, algorithm=\"randomized\", n_iter=7, random_state=42)\nZ_sparse = tsvd.fit_transform(R_sparse)\nR_recon = Z_sparse @ tsvd.components_\nobs_rmse = float(np.sqrt(np.mean((R_sparse.toarray()[mask] - R_recon[mask]) ** 2)))\nprint(\n    f\"TruncatedSVD Sparse ({R_sparse.shape}, nnz={R_sparse.nnz}, density={100*R_sparse.nnz/(n_users*n_items):.1f}%): \"\n    f\"ExplainedVar={tsvd.explained_variance_ratio_.sum()*100:.2f}% | ObservedRMSE={obs_rmse:.4f}\"\n)\n\n# 2. Dense PCA: Full SVD vs Randomized SVD (Halko-Martinsson-Tropp)\nn_samples, n_features, k_dense = 800, 100, 8\nU_d = rng.standard_normal((n_samples, k_dense))\nV_d = rng.standard_normal((n_features, k_dense))\nX_dense = U_d @ np.diag(np.linspace(15.0, 2.0, k_dense)) @ V_d.T + rng.normal(0.0, 0.25, size=(n_samples, n_features))\n\npca_full = PCA(n_components=k_dense, svd_solver=\"full\").fit(X_dense)\npca_rand = PCA(n_components=k_dense, svd_solver=\"randomized\", random_state=42).fit(X_dense)\n\nmax_sv_diff = float(np.max(np.abs(pca_full.singular_values_ - pca_rand.singular_values_)))\n# Ukur keselarasan subruang via nilai singular dari V_full @ V_rand^T (cosinus sudut prinsipal)\nprincipal_cos = np.linalg.svd(pca_full.components_ @ pca_rand.components_.T, compute_uv=False)\nprint(\n    f\"PCA Full vs Randomized (k={k_dense}): \"\n    f\"VarFull={pca_full.explained_variance_ratio_.sum()*100:.4f}% | \"\n    f\"VarRand={pca_rand.explained_variance_ratio_.sum()*100:.4f}%\"\n)\nprint(\n    f\"Max |sigma_full - sigma_rand|={max_sv_diff:.2e} | \"\n    f\"Min Principal Angle Cosine={principal_cos.min():.8f}\"\n)",
