          "code": "import numpy as np\nfrom scipy.linalg import cho_factor, cho_solve, qr, solve_triangular\nfrom sklearn.linear_model import Ridge\n\nrng = np.random.default_rng(42)\nn, d = 250, 10\n\n# Bangun matriks desain X dengan condition number terkontrol kappa(X) = 1e7\nU, _ = np.linalg.qr(rng.standard_normal((n, d)))\nV, _ = np.linalg.qr(rng.standard_normal((d, d)))\nsigmas = np.logspace(0, -7, d)\nX = U @ np.diag(sigmas) @ V.T\nw_true = np.array([2.5, -1.3, 0.8, 1.9, -0.7, 0.4, -2.1, 1.1, 0.6, -1.5])\ny = X @ w_true\n\nprint(f\"kappa_2(X)     = {np.linalg.cond(X):.3e}\")\nprint(f\"kappa_2(X^T X) = {np.linalg.cond(X.T @ X):.3e}  (kuadratisasi!)\")\n\n\ndef report(label: str, w_hat: np.ndarray) -> None:\n    rel_err = float(np.linalg.norm(w_hat - w_true) / np.linalg.norm(w_true))\n    digits = max(0.0, -np.log10(max(rel_err, 1e-16)))\n    print(f\"  {label:<32s} | RelErr={rel_err:.3e} | Digit Akurat~{digits:5.2f}\")\n\n\n# 1. Anti-pattern: Explicit matrix inverse pada Normal Equations\nw_inv = np.linalg.inv(X.T @ X) @ (X.T @ y)\nreport(\"1. inv(X^T X) @ X^T y [BAD]\", w_inv)\n\n# 2. Normal Equations + Cholesky (masih mengkuadratkan kappa!)\nc_fac = cho_factor(X.T @ X)\nw_chol = cho_solve(c_fac, X.T @ y)\nreport(\"2. Cholesky(X^T X)    [WARN]\", w_chol)\n\n# 3. Householder QR langsung pada X (tanpa membentuk X^T X)\nQ, R = qr(X, mode=\"economic\")\nw_qr = solve_triangular(R, Q.T @ y)\nreport(\"3. Householder QR(X)  [SAFE]\", w_qr)\n\n# 4. SVD Least Squares (np.linalg.lstsq)\nw_svd, *_ = np.linalg.lstsq(X, y, rcond=None)\nreport(\"4. SVD lstsq(X, y)    [SAFE]\", w_svd)\n\n# 5. Scikit-Learn Ridge (alpha=1e-4 menstabilkan spektrum SPD: cholesky vs svd identik)\nw_ridge_chol = Ridge(alpha=1e-4, fit_intercept=False, solver=\"cholesky\").fit(X, y).coef_\nw_ridge_svd = Ridge(alpha=1e-4, fit_intercept=False, solver=\"svd\").fit(X, y).coef_\nprint(f\"  5. Ridge(1e-4) ||w_chol - w_svd||_2 = {float(np.linalg.norm(w_ridge_chol - w_ridge_svd)):.3e} (konsisten saat SPD!)\")",
