          "code": "import numpy as np\nfrom scipy.special import log_softmax, logsumexp, softmax\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(42)\n\n# 1. SciPy Stable Log-Sum-Exp & Multi-Class Cross-Entropy pada Logit Skala Ekstrem\nlogits_batch = np.array([\n    [950.0, 952.0, 949.5],\n    [-950.0, -948.0, -950.5],\n    [0.2, 2.2, -0.3],\n], dtype=np.float64)\ny_true = np.array([1, 1, 1])\n\nlse_vals = logsumexp(logits_batch, axis=1)\nprobs = softmax(logits_batch, axis=1)\nlprobs = log_softmax(logits_batch, axis=1)\nce_loss = float(-np.mean(lprobs[np.arange(len(y_true)), y_true]))\n\nprint(\"=== SCIPY STABLE LOG-SUM-EXP & SOFTMAX ===\")\nfor i in range(len(logits_batch)):\n    print(f\"  Row {i}: LSE={lse_vals[i]:9.4f} | probs={[round(float(p), 5) for p in probs[i]]}\")\nprint(f\"Shift-Invariant Cross-Entropy Loss (3 baris identik secara relatif): {ce_loss:.6f}\")\n\n# 2. Scikit-Learn StandardScaler.partial_fit (Chan-Welford Pairwise Update) vs Naif Streaming\nn_batches, batch_size = 10, 500\noffset = 1e9\nbatches = [offset + rng.normal(0.0, 2.5, size=(batch_size, 2)) for _ in range(n_batches)]\nfull_centered = np.vstack(batches) - offset\nexact_std = np.std(full_centered, axis=0, ddof=0)\n\nscaler = StandardScaler()\nsum_x = np.zeros(2, dtype=np.float64)\nsum_x2 = np.zeros(2, dtype=np.float64)\ntotal_n = 0\nfor b in batches:\n    scaler.partial_fit(b)\n    sum_x += np.sum(b, axis=0)\n    sum_x2 += np.sum(b ** 2, axis=0)\n    total_n += len(b)\n\nnaive_var = (sum_x2 / total_n) - (sum_x / total_n) ** 2\nnaive_std = np.sqrt(np.maximum(naive_var, 0.0))\n\nprint(\"=== STREAMING STANDARDIZATION (10 Batch x 500 Baris, Offset 1e9) ===\")\nprint(f\"Std Eksak (Terpusat)        : {np.round(exact_std, 6).tolist()}\")\nprint(f\"StandardScaler.partial_fit  : {np.round(scaler.scale_, 6).tolist()} (ErrMax={np.max(np.abs(scaler.scale_-exact_std)):.2e})\")\nprint(f\"Naif sum(x^2)/N - mean^2    : {np.round(naive_std, 6).tolist()} (ErrMax={np.max(np.abs(naive_std-exact_std)):.2e})\")",
